//! 🧪️ The actual decoder preserves a producer-owned reply and invoices work during unwind.
use semio_framework_value_native_decoding::*;
use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
struct Work(Arc<AtomicUsize>);
impl OriginalWorkRecipient for Work{
 type Context<'turn,'source>=() where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn admits<'reply,'turn,'source>(&mut self,_:&mut (),reply:OriginalWorkQuote<'reply>,_:u64,_:u64)->OriginalWorkQuoteComplete<'reply>where 'source:'turn{reply.complete(Ok(true))}
 fn settle_partial<'reply,'turn,'source>(&mut self,_:&mut (),reply:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{self.0.fetch_add(1,Ordering::Relaxed);reply.complete(Ok(()))}
 fn recover_partial<'reply,'turn,'source>(&mut self,_:&mut (),reply:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{reply.pending()}
}
struct Physical;
impl OriginalConstructionRecipient for Physical{
 type Context<'turn,'source>=()where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn grant<'reply,'turn,'source>(&mut self,_:&mut (),reply:OriginalConstructionGrant<'reply>)->OriginalConstructionGrantComplete<'reply>where 'source:'turn{let d=reply.demand();reply.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}))}
 fn accept<'reply,'turn,'source>(&mut self,_:&mut (),reply:OriginalConstructionAccept<'reply>)->OriginalConstructionAcceptComplete<'reply>where 'source:'turn{assert_eq!(reply.actual(),None);reply.complete(Ok(()))}
 fn submitted<'turn,'source>(&self,_:&())->RetainedCloneProgress where 'source:'turn{Default::default()}
}
struct Producer{error:Option<ValueError>,receives:Arc<AtomicUsize>,recovers:Arc<AtomicUsize>,units:u64}
impl OriginalEffectProducer for Producer{
 type Output=RetainedCloneStep;type Failure=ValueError;type Context<'turn,'source>=()where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn receive<'reply,'turn,'source>(&mut self,_:&mut (),effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{self.receives.fetch_add(1,Ordering::Relaxed);assert!(effect.performed(self.units)?);let completed=reply.complete(Err(self.error.take().unwrap()));std::hint::black_box(&completed);panic!("original reply recorded before producer unwind")}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut (),_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>where 'source:'turn{self.recovers.fetch_add(1,Ordering::Relaxed);Ok(reply.pending())}
}
fn turn<T>(work:&mut OriginalWorkAuthority<Work>,physical:&mut OriginalConstructionAuthority<Physical>,native:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<T,ValueError>{work.with_loan(&mut (),|loan|native.with_work_recipient(loan,|native|physical.with_loan(&mut (),|loan|native.with_construction_recipient(loan,operation))?))?}
#[test]
fn original_reply_survives_unwind_and_transfers_after_actual_partial_validation(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("original-effect.json")).unwrap();let error=ValueError::new(ValueRefusalKind::InvalidValue,fixture["reply"].as_str().unwrap());let pointer=error.message.as_ptr();let receives=Arc::new(AtomicUsize::new(0));let recovers=Arc::new(AtomicUsize::new(0));let checks=Arc::new(AtomicUsize::new(0));let mut authority=OriginalEffectAuthority::new(Producer{error:Some(error),receives:receives.clone(),recovers:recovers.clone(),units:fixture["performed"].as_u64().unwrap()});let mut work=OriginalWorkAuthority::new(Work(checks.clone()));let mut physical=OriginalConstructionAuthority::new(Physical);let mut observer=|_|true;let mut native=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::default();let demand=RetirementDemand{depth:1,..Default::default()};let maximum=fixture["quoted"].as_u64().unwrap();
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||turn(&mut work,&mut physical,&mut native,|control|control.receive_original_effect(demand,maximum,&mut frame,&mut authority,|_,effect,authority,action|authority.drive(&mut (),effect,action)))));
 assert!(interrupted.is_err());assert_eq!(native.actual_work(),u128::from(fixture["expected"]["committedBeforeRecovery"].as_u64().unwrap()));assert!(authority.has_pending_action());assert_eq!(checks.load(Ordering::Relaxed),0);
 let poll=turn(&mut work,&mut physical,&mut native,|control|control.receive_original_effect(demand,maximum,&mut frame,&mut authority,|_,effect,authority,action|authority.drive(&mut (),effect,action))).unwrap();
 let NativeReceivingEffectPoll::Complete(turn)=poll else{panic!("recorded original reply remained pending")};assert_eq!(turn.work,u128::from(fixture["performed"].as_u64().unwrap()));let failure=turn.result.unwrap_err();assert_eq!(failure.child.unwrap().message.as_ptr(),pointer);assert_eq!(receives.load(Ordering::Relaxed),fixture["expected"]["receiveCalls"].as_u64().unwrap()as usize);assert_eq!(recovers.load(Ordering::Relaxed),fixture["expected"]["recoverCalls"].as_u64().unwrap()as usize);assert_eq!(checks.load(Ordering::Relaxed),fixture["expected"]["partialChecks"].as_u64().unwrap()as usize);assert!(!native.has_pending_work());assert!(!authority.has_pending_action());assert!(authority.into_producer().is_ok());assert!(physical.into_recipient().is_ok());assert!(work.into_recipient().is_ok());
}

struct RecipientProducer{recipient:NativeDecodeRetirementRecipient}
impl OriginalEffectProducer for RecipientProducer{
 type Output=RetainedCloneStep;type Failure=semio_framework_value_retirement::OriginalRetirementFailure;type Context<'turn,'source>=()where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn receive<'reply,'turn,'source>(&mut self,_:&mut (),effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,Self::Failure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,Self::Failure>,ValueError>where 'source:'turn{Ok(match ErasedSnapshotRetirement::close_step(&mut self.recipient,effect){RetainedWorkPoll::Pending{..}=>reply.pending(),RetainedWorkPoll::Complete(turn)=>reply.complete(turn.result)})}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut (),_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,Self::Failure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,Self::Failure>,ValueError>where 'source:'turn{Ok(reply.pending())}
}
#[test]
fn actual_reserved_recipient_close_records_work_in_the_original_sink(){
 let all:serde_json::Value=serde_json::from_str(include_str!("original-effect.json")).unwrap();let law=&all["recipientClose"];let mut recipient=NativeDecodeRetirementRecipient::new();recipient.reserve().unwrap();let mut authority=OriginalEffectAuthority::new(RecipientProducer{recipient});let checks=Arc::new(AtomicUsize::new(0));let mut work=OriginalWorkAuthority::new(Work(checks.clone()));let mut physical=OriginalConstructionAuthority::new(Physical);let mut observer=|_|true;let mut native=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::default();let demand=authority.inspect(|producer|ErasedSnapshotRetirement::next_demand(&producer.recipient,4096)).unwrap();
 assert_eq!(demand.copy_bytes,law["copyBytes"].as_u64().unwrap()as usize);
 let poll=turn(&mut work,&mut physical,&mut native,|control|control.receive_original_effect(demand,law["work"].as_u64().unwrap(),&mut frame,&mut authority,|_,effect,authority,action|authority.drive(&mut (),effect,action))).unwrap();
 let NativeReceivingEffectPoll::Complete(turn)=poll else{panic!("reserved header close remained pending")};assert_eq!(turn.work,u128::from(law["work"].as_u64().unwrap()));assert_eq!(turn.result.unwrap().progress().copied_bytes,demand.copy_bytes);assert_eq!(native.actual_work(),turn.work);assert_eq!(checks.load(Ordering::Relaxed),1);let producer=authority.into_producer().ok().unwrap();assert!(ErasedSnapshotRetirement::terminal_is_empty(&producer.recipient));assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());
}

struct BirthProbe{ledger:NativeAllocationIdentity,recipient:Option<u64>}
struct BirthCursor{ledger:NativeAllocationIdentity,recipient:Option<u64>,phase:u8}
impl semio_framework_value_retirement::RetireOwned for BirthProbe{type RetirementCursor=BirthCursor;fn retirement_seed(self)->Self::RetirementCursor{BirthCursor{ledger:self.ledger,recipient:self.recipient,phase:0}}fn controlled_retirement_supported()->bool{true}}
impl semio_framework_value_retirement::retirement::RetirementCursor for BirthCursor{
 fn requires_original_birth(&self)->bool{self.phase==0}
 fn close_original_birth_step(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->semio_framework_value_retirement::retirement::RetirementStep{use semio_framework_value_retirement::retirement::RetirementStep;if grant.maximum_items==0||grant.maximum_copy_bytes<1{return RetirementStep::Pending(0)}assert_eq!(original.ledger_identity(),self.ledger);assert_eq!(original.retirement_recipient_identity(),self.recipient);match original.prepare_work(1){Ok(true)=>{},Ok(false)=>return RetirementStep::Pending(0),Err(error)=>return RetirementStep::Failure(error.into(),0)}if let Err(error)=original.commit_work(1){return RetirementStep::Failure(error.into(),0)}self.phase=1;RetirementStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()},1)}
 fn next_computational_work(&self,_:usize)->Result<u64,ValueError>{Ok(u64::from(self.phase<2))}
 fn next_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(if self.phase<2{RetirementDemand{copy_bytes:1,depth:1,..Default::default()}}else{Default::default()})}
 fn close_step(&mut self,effect:&mut RetainedAllocationEffect<'_>)->semio_framework_value_retirement::retirement::RetirementStep{use semio_framework_value_retirement::retirement::RetirementStep;if self.phase==0{return RetirementStep::Failure(ValueError::invariant("birth must precede ordinary close").into(),0)}if self.phase==2{return RetirementStep::Complete(0)}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetirementStep::Failure(ValueError::literal(ValueRefusalKind::WorkLimit,"probe close work overrun").into(),1),Err(error)=>return RetirementStep::Failure(error.into(),1)}self.phase=2;RetirementStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()},1)}
 fn terminal_is_empty(&self)->bool{self.phase==2}
 fn terminal_release_bytes(&self)->Option<usize>{Some(std::mem::size_of::<Self>())}
}
struct ControlledProbeProducer;
impl OriginalEffectProducer for ControlledProbeProducer{type Output=RetainedCloneStep;type Failure=semio_framework_value_retirement::OriginalRetirementFailure;type Context<'turn,'source>=&'turn mut semio_framework_value_retirement::retirement::controlled::ControlledRetirement<BirthProbe> where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn receive<'reply,'turn,'source>(&mut self,owner:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,Self::Failure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,Self::Failure>,ValueError>where 'source:'turn{let before=effect.performed_work();let turn=owner.step(effect);assert_eq!(turn.work(),effect.performed_work()-before);Ok(match turn{RetainedWorkPoll::Pending{..}=>reply.pending(),RetainedWorkPoll::Complete(turn)=>reply.complete(turn.result)})}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,Self::Failure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,Self::Failure>,ValueError>where 'source:'turn{Ok(reply.pending())}
}
struct PhysicalAlloc;
impl OriginalConstructionRecipient for PhysicalAlloc{type Context<'turn,'source>=() where 'source:'turn;fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}fn grant<'reply,'turn,'source>(&mut self,_:&mut (),reply:OriginalConstructionGrant<'reply>)->OriginalConstructionGrantComplete<'reply>where 'source:'turn{let d=reply.demand();reply.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}))}fn accept<'reply,'turn,'source>(&mut self,_:&mut (),reply:OriginalConstructionAccept<'reply>)->OriginalConstructionAcceptComplete<'reply>where 'source:'turn{assert!(reply.progress().fits(reply.grant()));if let Some(actual)=reply.actual(){assert_eq!(actual,reply.progress().retained_capacity_bytes)}reply.complete(Ok(()))}fn submitted<'turn,'source>(&self,_:&())->RetainedCloneProgress where 'source:'turn{Default::default()}}
fn turn_alloc<T>(work:&mut OriginalWorkAuthority<Work>,physical:&mut OriginalConstructionAuthority<PhysicalAlloc>,native:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<T,ValueError>{work.with_loan(&mut (),|loan|native.with_work_recipient(loan,|native|physical.with_loan(&mut (),|loan|native.with_construction_recipient(loan,operation))?))?}
#[test]
fn controlled_frontier_uses_actual_original_birth_loan(){let fixture:serde_json::Value=serde_json::from_str(include_str!("original-effect.json")).unwrap();let law=&fixture["controlledBirth"];let mut recipient=NativeDecodeRetirementRecipient::new();let mut observer=|_|true;let mut native=NativeDecodeControl::new(1<<20,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let ledger=native.ledger_identity();let recipient_id=native.retirement_recipient_identity();let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(BirthProbe{ledger,recipient:recipient_id}).ok().unwrap();let checks=Arc::new(AtomicUsize::new(0));let mut work=OriginalWorkAuthority::new(Work(checks));let mut physical=OriginalConstructionAuthority::new(PhysicalAlloc);let mut producer=OriginalEffectAuthority::new(ControlledProbeProducer);let mut frame=NativeReceivingEffect::default();for _ in 0..64{if owner.requires_original_birth(){break}let demand=owner.next_demand(4096).unwrap();let units=owner.next_computational_work(4096).unwrap();let poll=turn_alloc(&mut work,&mut physical,&mut native,|control|control.receive_original_effect(demand,units,&mut frame,&mut producer,|_,effect,producer,action|producer.drive(&mut &mut owner,effect,action))).unwrap();match poll{NativeReceivingEffectPoll::Complete(turn)=>{turn.result.unwrap();},NativeReceivingEffectPoll::Pending{..}=>panic!("original frontier effect remained pending")}}assert!(owner.requires_original_birth());let mut grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:64};let mut denied=grant;denied.maximum_copy_bytes=law["deniedCopyBytes"].as_u64().unwrap()as usize;let poll=turn_alloc(&mut work,&mut physical,&mut native,|control|control.with_retirement(denied,|funding|funding.with_original_close(|original|Ok(owner.step_original_birth(original,denied))))).unwrap();let RetainedWorkPoll::Complete(denied_turn)=poll else{panic!("unstarted denied Birth incorrectly remained pending")};assert_eq!(denied_turn.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert_eq!(denied_turn.result.unwrap().progress(),RetainedCloneProgress::default());assert!(owner.requires_original_birth());let poll=turn_alloc(&mut work,&mut physical,&mut native,|control|control.with_retirement(grant,|funding|funding.with_original_close(|original|Ok(owner.step_original_birth(original,grant))))).unwrap();let RetainedWorkPoll::Complete(turn)=poll else{panic!("funded original Birth stayed pending")};assert_eq!(turn.work,u128::from(law["selectedWork"].as_u64().unwrap()));assert_eq!(turn.result.unwrap().progress().copied_bytes,law["copiedBytes"].as_u64().unwrap()as usize);assert!(!owner.requires_original_birth());for _ in 0..64{if owner.terminal_is_empty(){break}let demand=owner.next_demand(4096).unwrap();let units=owner.next_computational_work(4096).unwrap();let poll=turn_alloc(&mut work,&mut physical,&mut native,|control|control.receive_original_effect(demand,units,&mut frame,&mut producer,|_,effect,producer,action|producer.drive(&mut &mut owner,effect,action))).unwrap();match poll{NativeReceivingEffectPoll::Complete(turn)=>{turn.result.unwrap();},NativeReceivingEffectPoll::Pending{..}=>panic!("original frontier effect remained pending")}}assert!(owner.terminal_is_empty());assert!(producer.into_producer().is_ok());assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());}

#[test]
fn actual_failure_pool_birth_uses_decoder_work_and_retains_original_physical_ownership(){
 use semio_framework_value_control_contract::OriginalFailureStorage;
 use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
 let all:serde_json::Value=serde_json::from_str(include_str!("original-effect.json")).unwrap();let law=&all["failureBirth"];let mut recipient=NativeDecodeRetirementRecipient::new();let mut observer=|_|true;let mut native=NativeDecodeControl::new(1<<20,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let ledger=native.ledger_identity();let recipient_id=native.retirement_recipient_identity();let checks=Arc::new(AtomicUsize::new(0));let mut work=OriginalWorkAuthority::new(Work(checks.clone()));let mut physical=OriginalConstructionAuthority::new(Physical);
 let demand=OriginalFailureStorage::birth_demand();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_depth:demand.depth,..Default::default()};
 let(poll,heap)=observe(||turn(&mut work,&mut physical,&mut native,|control|Ok(control.prepare_failure_storage(grant))).unwrap());let RetainedWorkPoll::Complete(birth)=poll else{panic!("actual failure allocation remained pending")};assert_eq!(birth.work,u128::from(law["work"].as_u64().unwrap()));let progress=birth.result.unwrap().progress();assert_eq!(heap,(OriginalFailureStorage::birth_bytes(),0));assert_eq!(progress.retained_capacity_bytes,heap.0);assert_eq!(progress.copied_bytes,demand.copy_bytes);assert_eq!(native.actual_work(),birth.work);assert_eq!(native.owned_bytes(),heap.0);assert_eq!(native.ledger_identity(),ledger);assert_eq!(native.retirement_recipient_identity(),recipient_id);assert_eq!(checks.load(Ordering::Relaxed),law["partialChecks"].as_u64().unwrap()as usize);assert!(native.has_retirement_failure_storage());assert!(!native.has_pending_work());drop(native);
 let mut authority=OriginalEffectAuthority::new(RecipientProducer{recipient});let mut observer=|_|true;let mut native=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::default();let demand=authority.inspect(|producer|ErasedSnapshotRetirement::next_demand(&producer.recipient,4096)).unwrap();let(poll,heap)=observe(||turn(&mut work,&mut physical,&mut native,|control|control.receive_original_effect(demand,1,&mut frame,&mut authority,|_,effect,authority,action|authority.drive(&mut (),effect,action))).unwrap());let NativeReceivingEffectPoll::Complete(closed)=poll else{panic!("actual prepaid node release remained pending")};assert_eq!(closed.work,u128::from(law["releaseWork"].as_u64().unwrap()));assert_eq!(heap,(0,OriginalFailureStorage::birth_bytes()));assert_eq!(closed.result.unwrap().progress().released_bytes,heap.1);assert_eq!(checks.load(Ordering::Relaxed),2);let producer=authority.into_producer().ok().unwrap();assert!(ErasedSnapshotRetirement::terminal_is_empty(&producer.recipient));assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());
}
